import numpy as np


def r(x):
    # Syntactically non-identity but semantically identity to preserve the
    # output of the strictly monotonic program program(x) = 6 + 3x.
    return float(np.sin(np.arcsin(x)))


def R(y_orig, y_new):
    # Trajectory similarity: outputs must be identical within numerical tolerance
    return abs(y_orig - y_new) <= 1e-6
